private lemma CircAnd_time_circuitSize (n : ℕ) (y : Fin n → FanInTwoCircuit Bool Bool) :
    ((CircAnd n y).time fanInTwoCircModel).circuitSize =
    (CircAnd.do_CircAnd n y).circuitSize

private lemma CircAnd_do_size : ∀ n : ℕ, ∀ x : Fin n → FanInTwoCircuit Bool Bool,
    (CircAnd.do_CircAnd n x).circuitSize
      ≤ 1 + 2 * n + (Fin.sum (FinVec.map FanInTwoCircuit.circuitSize x))

private lemma CircAndSimple_time_circuitSize (n : ℕ) (y : Fin n → Bool) :
    ((CircAndSimple n y).time fanInTwoCircModel).circuitSize =
    (CircAndSimple.do_CircAnd n y).circuitSize

private lemma tail_image_subset (m : ℕ) (x : Fin (m + 1) → FanInTwoCircuit Bool Bool) :
    Finset.univ.image (fun i : Fin m => (Fin.tail x i).depthOf) ⊆
    Finset.univ.image (fun i : Fin (m + 1) => (x i).depthOf)

private lemma tail_max_le_full_max (m : ℕ) (x : Fin (m + 1) → FanInTwoCircuit Bool Bool) :
    (Finset.univ.image (fun i : Fin m => (Fin.tail x i).depthOf)).max.getD 0 ≤
    (Finset.univ.image (fun i : Fin (m + 1) => (x i).depthOf)).max.getD 0

private lemma head_le_full_max (m : ℕ) (x : Fin (m + 1) → FanInTwoCircuit Bool Bool) :
    (x 0).depthOf ≤
    (Finset.univ.image (fun i : Fin (m + 1) => (x i).depthOf)).max.getD 0

theorem wpH_liftBind (H : LHandler F ps) {ι : Type u}
